@namespace sv_ac6746aff7e94b48abdbba1d7290b9cf.Components.Pages.Settings
@using sv_ac6746aff7e94b48abdbba1d7290b9cf.Services

<h6 class="fw-semibold mb-3">Active Sessions</h6>

<div class="table-responsive">
    <table class="table table-hover align-middle">
        <thead class="table-light">
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
