.settings-sidebar {
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 0.5rem 0;
    border: 1px solid #e9ecef;
    position: sticky;
    top: 1rem;
}

.settings-sidebar .nav-link {
    color: #495057;
    padding: 0.6rem 1rem;
    border-radius: 0;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

/* Section panels */
.settings-section {
    background: #fff;
    border: 1px solid #e9ecef;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

