@page "/settings"
@namespace sv_ac6746aff7e94b48abdbba1d7290b9cf.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-nav">
        <SettingsSidebar ActiveSection="@_activeSection"
                         OnSectionChanged="section => _activeSection = section" />
    </div>
    <div class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-dashboard {
    display: flex;
    gap: 1.5rem;
    min-height: 600px;
}

.settings-nav {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

/* Sidebar */
.settings-sidebar {
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 0.5rem 0;
    border: 1px solid #e9ecef;
    position: sticky;
    top: 1rem;
}

.settings-sidebar .nav-link {
    color: #495057;
    padding: 0.6rem 1rem;
    border-radius: 0;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

/* Section panels */
.settings-section {
    background: #fff;
    border: 1px solid #e9ecef;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

